def exl(kind):
    out = []
    for j in EXJ:
        if not j[5].startswith(kind): continue
        out.append(f"{d_(j[1])} {KN[j[2]]}전 {j[3]}분 {KN[j[4]]}" + (" PK" if kind == "PK" else " 자책골" if kind == "상대" else " 골"))
    return ", ".join(out)
def nex(kind): return sum(1 for j in EXJ if j[5].startswith(kind))
N_FM = sum(1 for a in A_STATUS if a[4] == "TM+FotMob")
N_TMONLY = sum(1 for a in A_STATUS if a[4].startswith("TM 단독"))
